/** PostgreSQL search baseline. The parameter placeholder must be generated by the query builder. */
export interface SearchProvider { clause(parameter:string):string }
export class PostgresSearch implements SearchProvider {
  clause(parameter:string):string {if(!/^\$[1-9][0-9]*$/.test(parameter))throw new Error("Invalid search parameter");return `to_tsvector('simple',r.title) @@ plainto_tsquery('simple',${parameter})`}
}
export const contentSearch:SearchProvider = new PostgresSearch();

